import React from 'react';

export default function CartItem({ item, onRemove }) {
  return (
    <div className="cart-item">
      <p>
        {item.name} x {item.qty}
      </p>
      <p>${item.price}</p>
      <button onClick={onRemove}>Remove</button>
    </div>
  );
}
